Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String line = br.readLine();
        int n = Integer.parseInt(line);
        String input = br.readLine();
        String pattern = "\\([\\w_]*\\)";
        String[] parts = input.split(pattern);
        int maxWordLength = 0;
        for (String s : parts) {
            maxWordLength = Math.max(maxWordLength, getLongestWord(s));
        }
        Pattern p = Pattern.compile(pattern);
        Matcher m = p.matcher(input);
        long countInside = 0;
        while (m.find()) {
            String inside = trimParentheses(m.group());
            countInside += Arrays.stream(inside.split("_"))
                                 .filter(str -> !str.isEmpty())
                                 .count();
        }
        pw.println(maxWordLength + " " + countInside);
        pw.flush();
    }

    private static int getLongestWord(String s) {
        return Arrays.stream(s.split("_"))
                     .mapToInt(String::length)
                     .max()
                     .orElse(0);
    }

    private static String trimParentheses(String s) {
        return s.substring(1, s.length() - 1);
    }
}
